'use strict';
const workbench={tab:'explore',source:'vault',project:null,expanded:new Set(),file:null,tabs:[],query:'',filter:null,mode:'split',busy:false};
const coreMain=renderMain,coreTabs=renderTabs;
let fileRequest=0;
const flatten=entries=>entries.flatMap(e=>[e,...(e.children?flatten(e.children):[])]);
const fileLabel=kind=>({markdown:'note',image:'image',file:'file',directory:'folder'}[kind]);
function projectFiles(){return workbench.project?flatten(workbench.project.entries).filter(e=>e.kind!=='directory'):[]}
function projectTree(entries,depth=0){return entries.map(e=>{const open=workbench.expanded.has(e.path);return `<div class="project-node"><button class="project-entry ${e.path===workbench.file?.path?'selected':''}" style="--depth:${depth}" ${e.kind==='directory'?`data-project-dir="${esc(e.path)}" aria-expanded="${open}"`:`data-project-file="${esc(e.path)}"`} title="${esc(e.path)}">${e.kind==='directory'?`<span class="tree-chevron ${open?'expanded':''}">${icon('chevron')}</span>`:'<span class="tree-spacer"></span>'}${icon(fileLabel(e.kind))}<span>${esc(e.name)}</span>${e.kind==='markdown'?'<small>MD</small>':''}</button>${e.children&&open?projectTree(e.children,depth+1):''}</div>`}).join('')}
function vaultTree(){return vault.folders.map(folder=>`<div><button class="project-entry" style="--depth:0" data-folder="${esc(folder)}" aria-expanded="${state.openFolders.has(folder)}"><span class="tree-chevron ${state.openFolders.has(folder)?'expanded':''}">${icon('chevron')}</span>${icon('folder')}<span>${esc(folder)}</span><small>${vault.notes.filter(n=>n.folder===folder).length}</small></button>${state.openFolders.has(folder)?vault.notes.filter(n=>n.folder===folder).map(n=>`<button class="project-entry ${state.id===n.id&&state.view==='notes'?'selected':''}" style="--depth:1" data-note="${esc(n.id)}"><span class="tree-spacer"></span>${icon('note')}<span>${esc(n.title)}</span>${n.favorite?'<small>✦</small>':''}</button>`).join(''):''}</div>`).join('')}
function searchResults(){const q=workbench.query.toLocaleLowerCase();if(workbench.source==='project')return projectFiles().filter(f=>(!workbench.filter||f.kind===workbench.filter)&&f.path.toLocaleLowerCase().includes(q)).map(f=>`<button class="side-result" data-project-file="${esc(f.path)}">${icon(fileLabel(f.kind))}<span>${esc(f.name)}<small>${esc(f.path)}</small></span></button>`).join('')||'<p class="side-empty">Nenhum arquivo encontrado.</p>';return vault.notes.filter(n=>(n.title+' '+n.body+' '+n.tags.join(' ')).toLocaleLowerCase().includes(q)).map(n=>`<button class="side-result" data-note="${esc(n.id)}">${icon('note')}<span>${esc(n.title)}<small>${esc(n.folder)}</small></span></button>`).join('')||'<p class="side-empty">Nenhuma nota encontrada.</p>'}
function collectionPanel(){if(workbench.source==='project'){const files=projectFiles();return `<div class="side-heading">ARQUIVOS POR TIPO</div>${[['markdown','Markdown'],['image','Imagens'],['file','Outros arquivos']].map(([type,label])=>`<button class="collection-entry" data-project-kind="${type}">${icon(fileLabel(type))}${label}<small>${files.filter(f=>f.kind===type).length}</small></button>`).join('')}<p class="side-empty">O projeto usa os arquivos da pasta selecionada. Nenhuma cópia é importada para o acervo.</p>`}return `<div class="side-heading">ACESSO RÁPIDO</div><button class="collection-entry" data-view="all">${icon('note')}Todas as notas<small>${vault.notes.length}</small></button><button class="collection-entry" data-view="favorites">${icon('star')}Favoritos<small>${vault.notes.filter(n=>n.favorite).length}</small></button><button class="collection-entry" data-action="daily">${icon('calendar')}Nota do dia</button><button class="collection-entry" data-action="templates">${icon('layers')}Modelos</button><button class="collection-entry" data-action="trash">${icon('trash')}Lixeira<small>${vault.trash.length}</small></button><div class="side-heading">TAGS</div><div class="side-tags">${[...new Set(vault.notes.flatMap(n=>n.tags))].map(t=>`<button class="tag-chip" data-tag="${esc(t)}"># ${esc(t)}</button>`).join('')}</div>`}
renderTree=function(){const project=workbench.source==='project',name=project?workbench.project?.name:'Meu universo';$('#sidebar').classList.add('workbench-sidebar');$('#sidebar').innerHTML=`<a class="brand" href="#" data-workspace-action="home" aria-label="Âmago, início"><img src="assets/amago-mark.svg" alt="" class="brand-logo"><span>âmago<span class="brand-dot">.</span></span><span class="beta">2.3</span></a><button class="workspace-picker" data-workspace-action="switch" title="Trocar workspace">${icon(project?'folder-open':'core')}<span><small>${project?'PROJETO LOCAL':'ESPAÇO PESSOAL'}</small><strong>${esc(name)}</strong></span>${icon('chevron')}</button>${!project?`<nav class="workspace-shortcuts" aria-label="Navegação principal"><button data-view="home" class="${state.view==='home'?'active':''}">${icon('home')}Central</button><button data-view="tasks" class="${state.view==='tasks'?'active':''}">${icon('check')}Tarefas</button><button data-view="graph" class="${state.view==='graph'?'active':''}">${icon('graph')}Mapa</button></nav>`:`<div class="project-location" title="${esc(workbench.project.root)}">${icon('folder')}${esc(workbench.project.name)}<span>${projectFiles().length} arquivos</span></div>`}<div class="sidebar-tabs" role="tablist" aria-label="Painéis da barra lateral">${[['explore','folder','Explorar'],['search','search','Buscar'],['collections','layers','Coleções']].map(([id,i,label])=>`<button role="tab" aria-selected="${workbench.tab===id}" aria-controls="sidebar-content" id="side-tab-${id}" tabindex="${workbench.tab===id?0:-1}" data-side-tab="${id}" class="${workbench.tab===id?'active':''}">${icon(i)}<span>${label}</span></button>`).join('')}</div><div class="sidebar-content" id="sidebar-content" role="tabpanel" aria-labelledby="side-tab-${workbench.tab}">${workbench.tab==='explore'?`<div class="tree-toolbar"><span>${project?'ARQUIVOS DO PROJETO':'SUAS NOTAS'}</span><div>${project?`<button class="icon-button" data-workspace-action="refresh" aria-label="Atualizar arquivos" title="Atualizar arquivos">${icon('refresh')}</button>`:''}<button class="icon-button" ${project?'data-workspace-action="new-folder"':'data-action="folder"'} aria-label="Criar pasta" title="Criar pasta">${icon('folder-plus')}</button><button class="icon-button" data-workspace-action="collapse" aria-label="Recolher pastas" title="Recolher pastas">${icon('collapse')}</button></div></div><div class="workspace-tree">${project?(projectTree(workbench.project.entries)||'<p class="side-empty">Pasta vazia. Crie um arquivo Markdown para começar.</p>'):vaultTree()}</div>${project&&workbench.project.truncated?'<p class="side-empty">A árvore foi limitada a 3.000 itens ou 12 níveis.</p>':''}${project&&workbench.project.warnings?'<p class="side-empty">Algumas pastas não puderam ser lidas.</p>':''}`:workbench.tab==='search'?`<div class="side-search">${icon('search')}<input id="side-query" placeholder="${project?'Buscar pelo nome do arquivo':'Buscar nas notas'}" aria-label="${project?'Buscar arquivos pelo nome':'Buscar notas'}" value="${esc(workbench.query)}"></div><div class="side-search-caption">${workbench.filter?`${esc(workbench.filter)} · `:''}${project?'Nome e caminho dos arquivos':'Título, conteúdo e tags'}</div><div id="side-results">${searchResults()}</div>`:collectionPanel()}</div><div class="workspace-footer"><button class="new-note" ${project?'data-workspace-action="new-file"':'data-action="new"'}>${icon('plus')}${project?'Novo arquivo .md':'Nova nota'}<kbd>Ctrl N</kbd></button><div class="workspace-footer-tools"><button data-workspace-action="open" title="Abrir pasta como projeto">${icon('folder-open')}Abrir pasta</button><button class="icon-button" data-action="settings" aria-label="Configurações" title="Configurações">${icon('settings')}</button></div></div>`;$('#side-query')?.addEventListener('input',e=>{workbench.query=e.target.value;$('#side-results').innerHTML=searchResults()})};
function markFileStatus(message){if(state.view==='project')$('#save-state').textContent=message}
async function saveProjectFile(){const f=workbench.file;if(!f?.dirty)return true;if(f.saving){await f.saving;return saveProjectFile()}const body=f.body,version=f.version;markFileStatus('Salvando arquivo…');f.saving=window.projectAdapter.save(f.path,body,version);let result;try{result=await f.saving}catch(e){result={error:e.message}}finally{f.saving=null}if(result.error||result.conflict){f.conflict=!!result.conflict;markFileStatus(result.conflict?'Conflito no disco':'Arquivo não salvo');toast(result.conflict?'O arquivo mudou no disco. Seu rascunho foi preservado.':result.error);if(workbench.source==='project'){state.view='project';render()}return false}f.version=result.version;f.savedBody=body;f.dirty=f.body!==body;f.conflict=false;markFileStatus(f.dirty?'Alterações pendentes':'Arquivo salvo');renderProjectBanner();return !f.dirty||saveProjectFile()}
function renderProjectBanner(){const holder=$('#project-message');if(!holder)return;const f=workbench.file;holder.innerHTML=f?.conflict?`<div class="project-warning"><strong>O arquivo foi alterado em outro programa.</strong><span>Seu rascunho continua aqui. Exporte-o antes de recarregar o conteúdo do disco.</span><button class="plain-button" data-workspace-action="export-draft">${icon('download')}Exportar rascunho</button><button class="plain-button" data-workspace-action="reload-file">${icon('refresh')}Recarregar do disco</button></div>`:''}
async function openProjectFile(path){const request=++fileRequest;if(!(await saveProjectFile())||request!==fileRequest)return;const entry=projectFiles().find(f=>f.path===path);if(!entry)return;if(entry.kind==='file'){toast('Este tipo aparece na árvore, mas não é executado nem editado pelo Âmago.');return}const result=await window.projectAdapter[entry.kind==='image'?'image':'read'](path);if(request!==fileRequest){if(result.url?.startsWith('blob:'))URL.revokeObjectURL(result.url);return}if(result.error){toast(result.error);return}const parents=path.split('/');for(let i=1;i<parents.length;i++)workbench.expanded.add(parents.slice(0,i).join('/'));if(workbench.file?.url?.startsWith('blob:'))URL.revokeObjectURL(workbench.file.url);workbench.file={...entry,...result,savedBody:result.body,dirty:false};if(!workbench.tabs.includes(path))workbench.tabs.push(path);state.view='project';state.tag=null;workbench.source='project';render();if(innerWidth<=650)document.body.classList.add('sidebar-hidden')}
function fileMarkdown(body){return markdown(body,false).replaceAll('data-wiki=','data-project-wiki=')}
function renderProject(){const f=workbench.file;$('#crumb-folder').textContent=workbench.project?.name||'Projeto';if(!f){$('#main').innerHTML=`<section class="project-empty"><div class="empty-project-icon">${icon('folder-open')}</div><div class="eyebrow">WORKSPACE LOCAL</div><h1>${esc(workbench.project.name)}</h1><p>Escolha um Markdown para escrever ou uma imagem para visualizar.<br>As alterações são salvas nos arquivos da sua pasta.</p><div><button class="solid-button" data-workspace-action="new-file">Novo arquivo .md</button><button class="plain-button" data-workspace-action="refresh">${icon('refresh')}Atualizar árvore</button></div><small>${esc(workbench.project.root)}</small></section>`;markFileStatus('Pasta conectada');projectStats();return}
$('#crumb-folder').textContent=workbench.project.name+' / '+f.path;$('#main').innerHTML=`<section class="project-document"><header class="project-document-toolbar"><div>${icon(fileLabel(f.kind))}<strong>${esc(f.name)}</strong><span>${Math.ceil(f.size/1024)} KB</span></div><div>${f.kind==='markdown'?`<div class="segmented"><button data-project-mode="edit" class="${workbench.mode==='edit'?'active':''}" title="Editar" aria-label="Editar arquivo">${icon('edit')}</button><button data-project-mode="split" class="${workbench.mode==='split'?'active':''}" title="Editor e prévia" aria-label="Editor e prévia">${icon('panel')}</button><button data-project-mode="read" class="${workbench.mode==='read'?'active':''}" title="Ler" aria-label="Ler arquivo">${icon('eye')}</button></div><button class="plain-button" data-workspace-action="save">${icon('save')}Salvar <kbd>Ctrl S</kbd></button>`:''}</div></header><div id="project-message"></div>${f.kind==='image'?`<div class="project-image"><img src="${esc(f.url)}" alt="${esc(f.name)}"><p>${esc(f.path)}</p></div>`:`<div class="project-editor-grid ${workbench.mode}">${workbench.mode!=='read'?`<textarea id="project-editor" aria-label="Editar arquivo Markdown" spellcheck="false">${esc(f.body)}</textarea>`:''}${workbench.mode!=='edit'?`<article class="markdown project-preview" id="project-preview">${fileMarkdown(f.body)}</article>`:''}</div>`}<footer class="project-file-footer"><span>${esc(f.path)}</span><span>${f.kind==='markdown'?'UTF-8 · Markdown · Ctrl S para salvar':'Prévia de imagem · arquivo original preservado'}</span></footer></section>`;
$('#project-editor')?.addEventListener('input',e=>{f.body=e.target.value;f.dirty=f.body!==f.savedBody;markFileStatus(f.dirty?'Alterações não salvas':'Arquivo salvo');if($('#project-preview'))$('#project-preview').innerHTML=fileMarkdown(f.body);projectStats()});$('#project-editor')?.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('  ',e.target.selectionStart,e.target.selectionEnd,'end');e.target.dispatchEvent(new Event('input'))}});renderProjectBanner();markFileStatus(f.dirty?'Alterações não salvas':'Arquivo no disco');projectStats()}
function projectStats(){const f=workbench.file;$('#connection-count').textContent=workbench.project.name;$('#word-count').textContent=f?.body?f.body.trim().split(/\s+/).filter(Boolean).length+' palavras':projectFiles().length+' arquivos';$('#reading-time').textContent='Pasta local'}
renderMain=function(){$('#crumb-workspace').textContent=state.view==='project'?'Projeto':'Meu universo';if(state.view==='project'){renderProject();return}coreMain()};
renderTabs=function(){if(workbench.source!=='project'){coreTabs();return}$('#tabbar').innerHTML=workbench.tabs.map(path=>`<button class="tab ${workbench.file?.path===path?'active':''}" data-project-file="${esc(path)}">${icon(fileLabel(projectFiles().find(f=>f.path===path)?.kind||'file'))}<span>${esc(path.split('/').at(-1))}</span></button>`).join('')+`<button class="tab-add" data-workspace-action="new-file" aria-label="Novo arquivo Markdown">${icon('plus')}</button>`};
async function refreshProject(){const result=await window.projectAdapter.tree();if(result.error){toast(result.error);return}workbench.project=result;renderTree()}
async function openProject(){if(!(await saveProjectFile()))return;const result=await window.projectAdapter.open();if(result.canceled)return;if(result.error){toast(result.error);return}fileRequest++;if(workbench.file?.url?.startsWith('blob:'))URL.revokeObjectURL(workbench.file.url);workbench.project=result;workbench.source='project';workbench.tab='explore';workbench.file=null;workbench.tabs=[];workbench.expanded=new Set(result.entries.filter(f=>f.kind==='directory').map(f=>f.path));workbench.query='';workbench.filter=null;state.view='project';state.tag=null;closeModal();render()}
function createProjectItem(kind){const parent=workbench.file?.path.split('/').slice(0,-1).join('/')||'';modal(kind==='directory'?'Nova pasta no projeto':'Novo arquivo Markdown',`<form id="project-create"><label for="project-name">Caminho relativo ao projeto</label><input id="project-name" class="field" value="${esc(parent?parent+'/':'')}" placeholder="${kind==='directory'?'notas':'notas/Minha nota.md'}" required><p>O arquivo será criado na pasta aberta. Os diretórios anteriores precisam existir.</p><div class="modal-actions"><button class="solid-button">Criar</button></div></form>`);$('#project-create').onsubmit=async e=>{e.preventDefault();let name=$('#project-name').value.trim();if(kind==='markdown'&&!/\.(md|markdown)$/i.test(name))name+='.md';const result=await window.projectAdapter.create(name,kind);if(result.error){toast(result.error);return}closeModal();await refreshProject();if(kind==='markdown')await openProjectFile(name);else{workbench.expanded.add(name);renderTree()}}}
const workActions={open:openProject,refresh:refreshProject,save:saveProjectFile,home:async()=>{if(!(await saveProjectFile()))return;workbench.source='vault';state.view='home';state.tag=null;render()},collapse:()=>{workbench.source==='project'?workbench.expanded.clear():state.openFolders.clear();renderTree()},'new-file':()=>createProjectItem('markdown'),'new-folder':()=>createProjectItem('directory'),switch:()=>{modal('Escolha seu workspace',`<div class="template-grid"><button data-workspace-action="vault">${icon('core')}<strong>Meu universo</strong><small>Notas, favoritos e conexões do acervo pessoal.</small></button>${workbench.project?`<button data-workspace-action="project">${icon('folder-open')}<strong>${esc(workbench.project.name)}</strong><small>Projeto local aberto nesta sessão.</small></button>`:''}<button data-workspace-action="open">${icon('folder-plus')}<strong>Abrir uma pasta</strong><small>Trabalhe diretamente com Markdown e imagens do seu computador.</small></button></div>`);},vault:async()=>{if(!(await saveProjectFile()))return;workbench.source='vault';state.view='home';state.tag=null;closeModal();render()},project:()=>{workbench.source='project';state.view='project';state.tag=null;closeModal();render()},'export-draft':()=>{const f=workbench.file;download(f.name.replace(/\.(md|markdown)$/i,'')+'-rascunho.md',f.body,'text/markdown;charset=utf-8')},'reload-file':()=>{modal('Recarregar do disco?',`<p>O rascunho aberto será substituído pelo conteúdo atual do arquivo. Exporte seu rascunho antes de continuar.</p><div class="modal-actions"><button class="plain-button" data-workspace-action="export-draft">Exportar rascunho</button><button class="solid-button" id="confirm-reload">Recarregar</button></div>`);$('#confirm-reload').onclick=async()=>{const f=workbench.file,result=await window.projectAdapter.read(f.path);if(result.error){toast(result.error);return}Object.assign(f,result,{savedBody:result.body,dirty:false,conflict:false});closeModal();renderProject()}}};
let replaying=false;
document.addEventListener('click',async e=>{const el=e.target.closest('[data-workspace-action],[data-side-tab],[data-project-file],[data-project-dir],[data-project-kind],[data-project-mode],[data-project-wiki]');
if(el){e.preventDefault();e.stopImmediatePropagation();try{if(el.dataset.workspaceAction)await workActions[el.dataset.workspaceAction]?.();if(el.dataset.sideTab==='search'){actions.search();return}if(el.dataset.sideTab){workbench.tab=el.dataset.sideTab;workbench.filter=null;renderTree();$('#side-tab-'+workbench.tab)?.focus()}if(el.dataset.projectFile)await openProjectFile(el.dataset.projectFile);if(el.dataset.projectDir){workbench.expanded.has(el.dataset.projectDir)?workbench.expanded.delete(el.dataset.projectDir):workbench.expanded.add(el.dataset.projectDir);renderTree()}if(el.dataset.projectKind){workbench.filter=el.dataset.projectKind;workbench.query='';actions.search()}if(el.dataset.projectMode){workbench.mode=el.dataset.projectMode;renderProject()}if(el.dataset.projectWiki){const target=el.dataset.projectWiki.replace(/\.md$/i,'').toLocaleLowerCase(),file=projectFiles().find(f=>f.kind==='markdown'&&(f.path.replace(/\.(md|markdown)$/i,'').toLocaleLowerCase()===target||f.name.replace(/\.(md|markdown)$/i,'').toLocaleLowerCase()===target));file?await openProjectFile(file.path):toast('Essa nota não foi encontrada no projeto.')}}catch(error){toast(error.message)}return}
const nav=e.target.closest('[data-note],[data-search-note],[data-view],[data-tag],[data-action="daily"],[data-action="new"],[data-action="search"]');if(nav&&(workbench.file?.dirty||(typeof studio!=='undefined'&&[...studio.files.values()].some(f=>f.dirty)))&&!replaying){e.preventDefault();e.stopImmediatePropagation();if(await saveProjectFile()){replaying=true;nav.click();replaying=false}return}if(nav?.matches('[data-note],[data-search-note],[data-view],[data-tag],[data-action="daily"],[data-action="new"]'))workbench.source='vault';
},true);
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab][data-side-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const ids=['explore','collections'],i=ids.indexOf(workbench.tab);workbench.tab=e.key==='Home'?ids[0]:e.key==='End'?ids.at(-1):ids[(i+1)%2];renderTree();$('#side-tab-'+workbench.tab).focus()}
if((e.ctrlKey||e.metaKey)&&workbench.source==='project'&&['s','n','k','e'].includes(e.key.toLowerCase())){e.preventDefault();e.stopImmediatePropagation();if(e.key.toLowerCase()==='e'&&workbench.file?.kind==='markdown'){workbench.mode=workbench.mode==='read'?'edit':'read';renderProject()}if(e.key.toLowerCase()==='s')saveProjectFile();if(e.key.toLowerCase()==='n')createProjectItem('markdown');if(e.key.toLowerCase()==='k')actions.search()}},true);
window.addEventListener('beforeunload',e=>{if(workbench.file?.dirty&&!window.amagoDesktop){e.preventDefault();e.returnValue=''}});
const previousFlush=window.amagoFlush;window.amagoFlush=async()=>{if(!(await saveProjectFile()))throw Error('O arquivo local não foi salvo.');await previousFlush?.()};
renderTree();

const personalOpenNote=openNote;
openNote=function(id){const go=()=>{fileRequest++;workbench.source='vault';personalOpenNote(id)};if(workbench.file?.dirty)return saveProjectFile().then(ok=>{if(ok)go()});go()};
const personalFocus=actions.focus,personalSearch=actions.search,personalCommands=actions.commands;
actions.focus=()=>state.view==='project'?document.body.classList.toggle('focus-mode'):personalFocus();
actions.search=()=>{if(workbench.source!=='project')return personalSearch();workbench.tab='search';renderTree();$('#side-query')?.focus()};
actions['open-project']=openProject;
commandList.unshift(['Abrir pasta como projeto','open-project','']);
actions.commands=()=>{if(workbench.source!=='project')return personalCommands();modal('Comandos do projeto','<div class="project-commands">'+[['save','Salvar arquivo','save'],['new-file','Novo arquivo Markdown','note'],['new-folder','Nova pasta','folder-plus'],['refresh','Atualizar árvore','refresh'],['open','Abrir outra pasta','folder-open'],['vault','Ir para Meu universo','core']].map(([action,label,glyph])=>'<button class="search-result" data-workspace-action="'+action+'">'+icon(glyph)+'<strong>'+label+'</strong></button>').join('')+'</div>')};
